// BCH over GF(2^7), reduction 0x09, t=23, n=127.
//
// All three stages wired together and verified end to end by tb_bch_e2e.v. The
// separate area probes this replaces measured a Chien stage that summed only t of
// the t+1 coefficients of the error locator - it left out the constant term, so its
// zero test was not the polynomial's zero test. That is the defect end-to-end
// decoding found and stage-wise synthesis could not.

`default_nettype none

module bch127t23_gf_mul_const #(parameter [6:0] C = 7'h02) (
    input  wire [6:0] a,
    output wire [6:0] y
);
    function [6:0] xtime(input [6:0] v);
        xtime = (v[6]) ? ((v << 1) ^ 7'h09) : (v << 1);
    endfunction
    reg [6:0] acc, cur;
    integer i;
    always @* begin
        acc = 7'h00;
        cur = a;
        for (i = 0; i < 7; i = i + 1) begin
            if (C[i]) acc = acc ^ cur;
            cur = xtime(cur);
        end
    end
    assign y = acc;
endmodule

// S_j <= S_j * alpha^j + bit, fed most significant position first, so that after n
// bits S_j = sum_i b_i alpha^(i*j).
module bch127t23_syndrome_bank (
    input  wire clk,
    input  wire rst_n,
    input  wire load,
    input  wire en,
    input  wire bit_in,
    output wire [7 * 2 * 23 - 1:0] syn
