    localparam [7 * 46 - 1:0] ALPHAS = {
        7'h1D,7'h4A,7'h25,7'h56,7'h2B,7'h51,7'h6C,7'h36,7'h1B,7'h49,7'h60,7'h30,7'h18,7'h0C,7'h06,7'h03,7'h45,7'h66,7'h33,7'h5D,7'h6A,7'h35,7'h5E,7'h2F,7'h53,7'h6D,7'h72,7'h39,7'h58,7'h2C,7'h16,7'h0B,7'h41,7'h64,7'h32,7'h19,7'h48,7'h24,7'h12,7'h09,7'h40,7'h20,7'h10,7'h08,7'h04,7'h02
    };
    genvar j;
    generate
        for (j = 0; j < 2 * 23; j = j + 1) begin : bank
            reg  [6:0] s;
            wire [6:0] scaled;
            bch127t23_gf_mul_const #(.C(ALPHAS[7*j +: 7])) mc (.a(s), .y(scaled));
            always @(posedge clk) begin
