// Chien search over all n positions. Q_k starts at lambda_k and is multiplied by
// alpha^k each cycle, so after c cycles the sum over k is Lambda(alpha^c). The k=0
// term is multiplied by alpha^0 = 1 and needs no multiplier, but it must be in the
// sum - leaving it out is the defect this file was written to remove.
module bch127t23_chien (
    input  wire clk,
    input  wire rst_n,
    input  wire start,
    input  wire en,
    input  wire [7 * (23+1) - 1:0] lambda,
    output wire root
);
    localparam [7 * 24 - 1:0] APOW = {
        7'h2F,7'h53,7'h6D,7'h72,7'h39,7'h58,7'h2C,7'h16,7'h0B,7'h41,7'h64,7'h32,7'h19,7'h48,7'h24,7'h12,7'h09,7'h40,7'h20,7'h10,7'h08,7'h04,7'h02,7'h01
    };
    wire [6:0] q [0:23];
    wire [6:0] chain [0:23];
    genvar k;
    generate
        for (k = 0; k <= 23; k = k + 1) begin : lanes
            reg  [6:0] acc;
            wire [6:0] stepped;
            bch127t23_gf_mul_const #(.C(APOW[7*k +: 7])) mc (.a(acc), .y(stepped));
            always @(posedge clk) begin
                if (!rst_n)     acc <= 7'h00;
                else if (start) acc <= lambda[7*k +: 7];
                else if (en)    acc <= stepped;
            end
            assign q[k] = acc;
        end
        assign chain[0] = q[0];
        for (k = 1; k <= 23; k = k + 1) begin : sum
            assign chain[k] = chain[k-1] ^ q[k];
        end
    endgenerate
    assign root = (chain[23] == 7'h00);
endmodule

